import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as memberService from "@/server/services/member-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as usageService from "@/server/services/usage-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("scratch: seat accounting", () => {
  it("removing a member frees the seat immediately (no prior recount)", async () => {
    const t = await createTenant("scratch-remove", "free");
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (!viewer) throw new Error("missing");

    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });

    const check = await billingService.checkLimit(t.org.id, "seats");
    expect(check.used).toBe(3);
    expect(check.remaining).toBe(0);
    expect(check.exceeded).toBe(true);
  });

  it("the periodic recount agrees with the removal and ignores archived rows", async () => {
    const t = await createTenant("scratch-recount", "growth");
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (!viewer) throw new Error("missing");
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });

    const recounted = await usageRepo.recomputeUsage(t.org.id);
    expect(recounted.seatsUsed).toBe(3);
    expect((await usageService.getUsage(t.actors.owner, t.org.id)).seatsUsed).toBe(3);
  });

  it("a removed member can be replaced: the freed seat is usable for a new invite", async () => {
    const t = await createTenant("scratch-reinvite", "free");
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (!viewer) throw new Error("missing");
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });

    await expect(
      invitationService.inviteMember(t.actors.owner, {
        orgId: t.org.id,
        email: "replacement@scratch-reinvite.test",
        role: "member",
      }),
    ).resolves.toBeDefined();
  });

  it("revoking a pending invitation gives its seat back; a full workspace is still refused", async () => {
    const t = await createTenant("scratch-revoke", "free");
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (!viewer) throw new Error("missing");
    const admin = await memberRepo.findMember(t.org.id, t.userIds.admin);
    if (!admin) throw new Error("missing");
    // Two members left (owner + member) on a 3-seat plan.
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: admin.id });

    const a = await invitationService.inviteMember(t.actors.owner, {
      orgId: t.org.id,
      email: "a@scratch-revoke.test",
      role: "member",
    });
    // 2 members + 1 pending = full.
    await expect(
      invitationService.inviteMember(t.actors.owner, {
        orgId: t.org.id,
        email: "b@scratch-revoke.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    await invitationService.revokeInvitation(t.actors.owner, a.id);
    await expect(
      invitationService.inviteMember(t.actors.owner, {
        orgId: t.org.id,
        email: "b@scratch-revoke.test",
        role: "member",
      }),
    ).resolves.toBeDefined();
    // Full again: 2 members + 1 pending.
    await expect(
      invitationService.inviteMember(t.actors.owner, {
        orgId: t.org.id,
        email: "c@scratch-revoke.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);
  });

  it("re-sending a pending invitation works in a full workspace", async () => {
    const t = await createTenant("scratch-resend", "free");
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (!viewer) throw new Error("missing");
    const admin = await memberRepo.findMember(t.org.id, t.userIds.admin);
    if (!admin) throw new Error("missing");
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: admin.id });

    const pending = await invitationService.inviteMember(t.actors.owner, {
      orgId: t.org.id,
      email: "d@scratch-resend.test",
      role: "member",
    });
    const resent = await invitationService.resendInvitation(t.actors.owner, pending.id);
    expect(resent.id).not.toBe(pending.id);
    expect(await invitationService.inviteMember(t.actors.owner, {
      orgId: t.org.id,
      email: "e@scratch-resend.test",
      role: "member",
    }).then(() => "ok", () => "refused")).toBe("refused");
  });
});
